const addM=(m,n,qty)=>{if(!n||!num(qty))return;m[n]=(m[n]||0)+num(qty)};
const priceTotal=m=>Object.entries(m).reduce((v,[k,n])=>v+price(k)*n,0);
const matSummary=m=>Object.entries(m).length?Object.entries(m).map(([n,q])=>({name:n,qty:q,unit:price(n),total:price(n)*q})):[];
const selectOptions=(arr,current)=>arr.map(n=>`<option value="${esc(n)}"${String(n)===String(current)?' selected':''}>${esc(n)}</option>`).join('');
const field=(name,key,value,type='number',min=0,step=1)=>`<label class="field">${esc(name)}<input data-set="${esc(key)}" type="${type}" value="${esc(value)}" ${type==='number'?`min="${min}" step="${step}"`:''}></label>`;
const sel=(name,key,choices,current)=>`<label class="field">${esc(name)}<select data-set="${esc(key)}">${selectOptions(choices,current)}</select></label>`;
const check=(name,key,value)=>`<label class="field checkbox"><input type="checkbox" data-set="${esc(key)}" ${value?'checked':''}>${esc(name)}</label>`;
