const materialsTable=m=>{const rows=matSummary(m);return rows.length?table(['Materiale','Quantità','Prezzo unitario','Totale'],rows.map(r=>`<tr><td><div class="material-pict">${iconFor(state.materialIds?.[r.name]||r.name,'◆')}<span>${esc(r.name)}</span></div></td><td>${count(r.qty)}</td><td>${cash(r.unit)}</td><td>${cash(r.total)}</td></tr>`)):'<p class="muted">Nessun materiale richiesto.</p>'};
