 const classKeys={Guerriero:'warrior',Ninja:'ninja',Sura:'sura',Sciamano:'shaman'};
 const classPortrait=(v)=>{const image=window.VERZUM_PNG_CLASSES?.[classKeys[v]];return validIcon(image)?`<img class="class-portrait" loading="lazy" decoding="async" src="${image}" alt="">`:''};
 const filters=`<div class="filter-title">CLASSE</div><div class="filter-row">${classes.map(v=>`<button class="filter-chip ${f.class===v?'active':''}" data-filter-class="${esc(v)}">${classPortrait(v)}${v==='all'?'Tutte':v}</button>`).join('')}</div><div class="filter-title">EQUIPAGGIAMENTO</div><div class="filter-row">${cats.map(v=>`<button class="filter-chip ${f.category===v?'active':''}" data-filter-category="${esc(v)}">${v==='all'?'Tutti':v}</button>`).join('')}</div>`;
 const list=filters+`<input id="item-search" class="control search" placeholder="Cerca tra ${state.catalog.length} oggetti..." aria-label="Cerca un oggetto"> <div class="item-list" id="item-list">${filtered.map(i=>`<button class="item-entry ${i.id===item.id?'active':''}" data-item="${esc(i.id)}" data-search-text="${esc(i.name.toLowerCase())}"><span class="tile-ico">${iconFor(i.id,i.symbol||categorySymbol[i.cat]||'◇')}</span><span><b>${esc(i.name)}</b><small>${esc(i.cat)} · ${Number(i.lv)?'Lv. '+i.lv+' · ':''}+0 / +${i.steps.length}</small></span></button>`).join('')||'<div class="empty">Nessun oggetto in questa categoria.</div>'}</div><p class="hint">${filtered.length} oggetti · ${countIcons()} icone importate</p>`;
 const levels=Array.from({length:item.steps.length+1},(_,i)=>i);
 const selectors=fieldset(sel('Da +','range.from',levels.filter(i=>i<item.steps.length),c.from)+sel('A +','range.to',levels.filter(i=>i>c.from),c.to)+field('Fallimenti predefiniti per passo','range.fail',state.range.fail));
 const evolve=item.evolution&&c.to===item.steps.length?`<div class="evolution-option">${check('Includi evoluzione +9 → '+(state.catalog.find(x=>x.id===item.evolution.to)?.name||item.evolution.to),'range.evolution',!!state.range.evolution)}</div>`:'';
