 const summary=`<div class="kpis upgrade-kpis"><div class="kpi"><small>Yang</small><strong>${cash(c.yang)}</strong><em title="${yangExact(c.yang)}">${yangExact(c.yang)}</em></div><div class="kpi"><small>Valore materiali</small><strong>${cash(priceTotal(c.materials))}</strong><em>${missingPrices?missingPrices+' senza prezzo':'Prezzi inseriti'}</em></div><div class="kpi total-green"><small>Costo totale</small><strong>${cash(c.total)}</strong><em>Yang + materiali</em></div><div class="kpi"><small>Fallimenti considerati</small><strong>${c.rows.reduce((v,r)=>v+r.attempts-1,0)}</strong><em>Probabilità primo tentativo: ${count(c.chance*100)}%</em></div></div>`;
 const scenarios=`<div class="scenario-row"><span>SCENARIO RAPIDO (PASSI NON SICURI):</span>${[0,1,2,3,4].map(v=>`<button class="filter-chip" data-scenario="${v}">${v===0?'Nessun fallimento':v+' fallimenti'}</button>`).join('')}</div>`;
 const token=(id,n,q)=>`<span class="material-token" title="${esc(n)} ×${q}">${iconFor(id,'◆','small')}${q>1?`<b>${count(q)}</b>`:''}</span>`;
 const stepMaterials=r=>{const list=r.isEvo?(item.evolution?.mats||[]).map(([id,q])=>[String(id),String(state.reference?.names?.[id]||id),q]):Object.entries(item.steps[r.idx]?.mat||{}).map(([n,q])=>[state.materialIds?.[n]||n,n,q]);return list.length?list.map(([id,n,q])=>token(id,n,q)).join(''):'<span class="muted">—</span>'};
 const fails=r=>{if(r.pct>=100)return '<span class="badge-success">Sicuro</span>';const n=r.attempts-1;return `<div class="fail-buttons">${[0,1,2,3,4].map(k=>`<button type="button" aria-label="${k} fallimenti" class="${n===k?'selected':''}" data-fail-choice="${r.idx}:${k}">${k}</button>`).join('')}<input type="number" class="control fail-many" min="5" max="500" placeholder="5+" data-fail-step="${r.idx}" aria-label="Altri fallimenti" value="${n>4?n:''}"></div>`};
