function petCalc(){
 const sys=state.reference?.sys?.pet;
 if(sys){const p=state.pet,lo=natural(p.from,1,104),hi=Math.min(105,Math.max(lo+1,natural(p.to,2,105))),materials={};let metins=0,yang=0,tries=0;
  const expPct=(level)=>{for(const [range,raw] of (sys.exp||[])){const a=String(range).split(/\s*[–-]\s*/).map(Number);if(level>=a[0]&&level<=(a[1]??a[0]))return Math.max(.1,parseFloat(String(raw).replace(',','.')))}return 100};
  for(let level=lo;level<hi;level++){metins+=100/expPct(level);for(const [from,to,id,q] of (sys.snack||[])){if(level>=from&&level<=to)addM(materials,state.reference.names[id]||String(id),q)}
   for(const evo of (sys.evo||[])){if(evo.lv!==level)continue;yang+=num(evo.y);for(const [id,q] of (evo.m||[]))addM(materials,state.reference.names[id]||String(id),q)}}
  const a=natural(p.fromType,1,5),b=Math.min(6,Math.max(a+1,natural(p.toType,2,6)));
  for(let i=a-1;i<b-1;i++){const step=sys.types?.[i];if(!step)continue;const n=1+Math.min(natural(p.fails?.[i]??p.fail,0,999),natural(step.p,0,999));tries+=n;addM(materials,state.reference.names[step.g]||String(step.g),n)}
  return {name:'Pet · livelli e tipo',levels:hi-lo,xp:0,metins:Math.ceil(metins),tries,materials,yang,total:yang+priceTotal(materials)};
 }
const p=state.pet,lv=Math.max(0,natural(p.to)-natural(p.from)),xp=lv*natural(p.expLevel),metins=Math.ceil(xp/Math.max(1,num(p.metinExp))),types=Math.max(0,natural(p.toType)-natural(p.fromType)),tries=types*(1+Math.min(natural(p.fail),Math.max(0,natural(p.pity)-1))),mat={};addM(mat,p.orb,tries);return {name:'Pet',levels:lv,xp,metins,tries,materials:mat,yang:Math.max(0,num(p.skills))*Math.max(0,num(p.skillCost)),total:priceTotal(mat)+Math.max(0,num(p.skills))*Math.max(0,num(p.skillCost))}}
