  for(let i=a;i<b;i++){if(i<10){const req=i+1,f=p.concentrated?0:natural(p.fails?.[i]??p.failReads,0,999),n=req+f;reads+=n;wait+=n*2;addM(m,p.book,n);rows.push({label:levels[i]+' → '+levels[i+1],success:req,attempts:n,material:p.book,index:i})}
  else{const n=Math.max(1,natural(p.stones?.[i]??1,1,999));reads+=n;stones+=n;wait+=n*4;addM(m,state.reference.names['50513']||'Pietra delle Anime',n);rows.push({label:levels[i]+' → '+levels[i+1],success:1,attempts:n,material:state.reference.names['50513']||'Pietra delle Anime',index:i})}}
